    az2_comp: {"src": "Вебинар 2", "time": "67:15", "n": "Слайд", "t": "Три зоны дуги", "s": "расширение · разворот · компрессия", "cap": "Схема на окклюзионном фото: впереди расширение с щёчным корневым торком, у первых моляров расширение с разворотом мезиально наружу, у вторых моляров — компрессия.", "at": {"f": "az_w02", "x": 1600, "y": 1800, "w": 794, "h": 450, "W": 3200, "H": 2250}},
