    az3_base: {"src": "Вебинар 3", "time": "5:15", "n": "Слайд", "t": "Основание черепа и рост", "s": "примат и человек", "cap": "Слева череп примата: окклюзионная плоскость горизонтальная, верхняя челюсть растёт в основном горизонтально. Справа череп человека: плоскость наклонная, рост в основном вертикальный.", "at": {"f": "az_w03", "x": 0, "y": 0, "w": 800, "h": 410, "W": 3200, "H": 1800}},
    az3_risky: {"src": "Вебинар 3", "time": "6:15", "n": "Слайд", "t": "«Рискованный сустав»", "s": "височно-нижнечелюстной сустав человека", "cap": "Анатомические препараты височно-нижнечелюстного сустава. Славичек называет его «рискованным»: защищавший сустав задний костный выступ утрачен, а нагрузка выросла.", "at": {"f": "az_w03", "x": 800, "y": 0, "w": 800, "h": 410, "W": 3200, "H": 1800}},
    az3_pies: {"src": "Вебинар 3", "time": "8:15", "n": "Слайд", "t": "II класс с XVIII по XXI век", "s": "португальская популяция", "cap": "Четыре диаграммы по векам: доля скелетных классов в португальской выборке черепов. Красный сектор — II класс — преобладает во всех веках.", "at": {"f": "az_w03", "x": 1600, "y": 0, "w": 800, "h": 410, "W": 3200, "H": 1800}},
    az3_ant: {"src": "Вебинар 3", "time": "13:15", "n": "Слайд", "t": "Переднее несоответствие — симптом", "s": "следствие заднего несоответствия", "cap": "Переднее несоответствие обычно симптом проблемы и часто следствие заднего несоответствия. «Эффект выдавливания» меняет окклюзионную плоскость и нарушает работу краниомандибулярной системы.", "at": {"f": "az_w03", "x": 2400, "y": 0, "w": 800, "h": 410, "W": 3200, "H": 1800}},
    az3_squeeze: {"src": "Вебинар 3", "time": "14:15", "n": "Слайд", "t": "Заднее несоответствие", "s": "эффект выдавливания", "cap": "Схема: без достаточного места позади для прорезывания зубов возникает «эффект выдавливания» → окклюзионные препятствия в боковом отделе → изменение окклюзионной плоскости.", "at": {"f": "az_w03", "x": 0, "y": 450, "w": 800, "h": 410, "W": 3200, "H": 1800}},
