    az3_pm: {"src": "Вебинар 3", "time": "19:15", "n": "Слайд", "t": "Чем опасно удаление премоляров", "s": "механическая ретракция передних зубов", "cap": "Схемы: механическая ретракция передних зубов после удаления премоляров опасна — передний отдел теряет функциональное пространство, нижняя челюсть отступает назад.", "at": {"f": "az_w03", "x": 1600, "y": 450, "w": 800, "h": 410, "W": 3200, "H": 1800}},
    az3_open: {"src": "Вебинар 3", "time": "20:15", "n": "Слайд", "t": "Юноша 19 лет", "s": "II класс, открытый прикус", "cap": "Список проблем: двусторонний перекрёстный прикус; окклюзионные препятствия в боковом отделе с выдвижением моляров; выраженный открытый прикус без передней направляющей.", "at": {"f": "az_w03", "x": 2400, "y": 450, "w": 800, "h": 410, "W": 3200, "H": 1800}},
    az3_res: {"src": "Вебинар 3", "time": "21:15", "n": "Слайд", "t": "Через 18 месяцев", "s": "без удаления премоляров и без операции", "cap": "Тот же пациент до и через 18 месяцев: открытый прикус закрыт, I класс с двух сторон. Удалены вторые моляры, зубы мудрости прорезались в окклюзию.", "at": {"f": "az_w03", "x": 0, "y": 900, "w": 800, "h": 410, "W": 3200, "H": 1800}},
    az3_dist: {"src": "Вебинар 3", "time": "25:15", "n": "Слайд", "t": "Исходно и восьмой элайнер", "s": "расширение и дистализация", "cap": "Сверху виртуальный план, снизу фото во рту: исходная дуга и дуга на восьмом элайнере. Что запланировано — то и получено.", "at": {"f": "az_w03", "x": 800, "y": 900, "w": 800, "h": 410, "W": 3200, "H": 1800}},
    az3_elast: {"src": "Вебинар 3", "time": "26:15", "n": "Слайд", "t": "Эластики II класса", "s": "рано: сначала вертикаль", "cap": "Пациентка с длинными эластиками II класса. Лектор считает это ошибкой порядка: до сагиттальной коррекции нужно исправить вертикальный компонент.", "at": {"f": "az_w03", "x": 1600, "y": 900, "w": 800, "h": 410, "W": 3200, "H": 1800}},
    az3_intr: {"src": "Вебинар 3", "time": "27:15", "n": "Слайд", "t": "Внедрение", "s": "передние зубы — до сагиттальной коррекции", "cap": "Овал выделяет выдвинутые передние зубы: их нужно внедрить раньше, чем исправлять переднезаднее соотношение, иначе их контакт оттолкнёт нижнюю челюсть назад.", "at": {"f": "az_w03", "x": 2400, "y": 900, "w": 800, "h": 410, "W": 3200, "H": 1800}},
    az3_exp: {"src": "Вебинар 3", "time": "37:15", "n": "Слайд", "t": "До и после: расширение", "s": "«синдром закрытой дуги»", "cap": "Верхний зубной ряд до и после лечения на элайнерах. Главное изменение — в поперечной плоскости: дуга расширена.", "at": {"f": "az_w03", "x": 0, "y": 1350, "w": 800, "h": 410, "W": 3200, "H": 1800}},
