    az4_chew: {"src": "Вебинар 4", "time": "18:15", "n": "Слайд", "t": "Жевательные валики", "s": "«мини-позиционер»", "cap": "Слева зуб отстал от элайнера — между краем зуба и капой виден зазор. Справа пациент прикусывает жевательный валик в этом месте, чтобы дожать зуб в капу.", "at": {"f": "az_w04", "x": 800, "y": 0, "w": 604, "h": 450, "W": 3200, "H": 2250}},
