    az4_case1: {"src": "Вебинар 4", "time": "25:15", "n": "Слайд", "t": "II класс, скученность, глубокий прикус", "s": "первый случай", "cap": "Взрослая пациентка: II класс, сильная скученность, глубокое резцовое перекрытие. Лечение — с удалением верхнего правого первого премоляра и мини-имплантатом.", "at": {"f": "az_w04", "x": 0, "y": 450, "w": 604, "h": 450, "W": 3200, "H": 2250}},
    az4_daher: {"src": "Вебинар 4", "time": "31:15", "n": "Слайд", "t": "Дистализация моляров", "s": "−1,4 мм ± 0,8", "cap": "Цефалометрическое исследование взрослых с мягким II классом без удаления на Invisalign (выборка Сэма Дахера): верхний первый моляр дистализирован в среднем на 1,4 мм.", "at": {"f": "az_w04", "x": 800, "y": 450, "w": 604, "h": 450, "W": 3200, "H": 2250}},
    az4_combo: {"src": "Вебинар 4", "time": "35:15", "n": "Слайд", "t": "«Комбо-обед»", "s": "эластики I класса к винтам и эластики II класса", "cap": "Мини-имплантаты сверху: эластики I класса от выреза-«слезы» к винту и эластики II класса. Окно под кнопку — дыроколом. Дистализация с опорой на винты создала место боковому резцу.", "at": {"f": "az_w04", "x": 1600, "y": 450, "w": 604, "h": 450, "W": 3200, "H": 2250}},
