    az4_space: {"src": "Вебинар 4", "time": "54:15", "n": "Слайд", "t": "Нет места — нет движения", "s": "ширина зуба и ширина промежутка", "cap": "Чёрная линия — ширина зуба, красная — доступная ширина в элайнере. Зуб шире промежутка: пока не создано место, он не выдвинется, какими бы ни были аттачменты.", "at": {"f": "az_w04", "x": 2400, "y": 900, "w": 604, "h": 450, "W": 3200, "H": 2250}},
    az4_sling: {"src": "Вебинар 4", "time": "65:15", "n": "Слайд", "t": "Обвивные эластики", "s": "внедрение боковых зубов", "cap": "Эластики sling идут от мини-имплантатов вокруг и поверх элайнера. Шесть винтов, на язычной стороне нижних моляров — вырезы-«слёзы». Так внедряют боковые зубы при открытом прикусе.", "at": {"f": "az_w04", "x": 0, "y": 1350, "w": 604, "h": 450, "W": 3200, "H": 2250}},
