    az4_vert: {"src": "Вебинар 4", "time": "69:15", "n": "Слайд", "t": "Знаете ли вы ограничения?", "s": "вертикальные вдавления", "cap": "Нижний ряд до Invisalign и сейчас: один зуб после первой фазы ещё развёрнут. Вертикальные вдавления в капе могут исправить это без нового уточняющего этапа.", "at": {"f": "az_w04", "x": 1600, "y": 1350, "w": 666, "h": 450, "W": 3200, "H": 2250}},
    az4_horiz: {"src": "Вебинар 4", "time": "71:15", "n": "Слайд", "t": "Горизонтальные щипцы", "s": "ретенция и торк", "cap": "Горизонтальное вдавление рядом с композитным аттачментом уменьшает «отставание»: усиливает контакт капы с аттачментом при экструзии или внедрении.", "at": {"f": "az_w04", "x": 2400, "y": 1350, "w": 604, "h": 450, "W": 3200, "H": 2250}},
    az4_tip: {"src": "Вебинар 4", "time": "72:15", "n": "Слайд", "t": "Моляр наклоняется мезиально", "s": "решение: мезиальный наклон корня", "cap": "Проблема: сопротивляясь торку передних зубов, первый моляр наклоняется мезиально и разобщается. Решение: добавить мезиальный наклон корня (выдвинуть мезиально-щёчный бугор).", "at": {"f": "az_w04", "x": 0, "y": 1800, "w": 604, "h": 450, "W": 3200, "H": 2250}},
    az4_wilson: {"src": "Вебинар 4", "time": "74:15", "n": "Слайд", "t": "Неверный торк боковых зубов", "s": "чрезмерная кривая Уилсона", "cap": "Модель сзади: нёбные бугры моляров свисают, кривая Уилсона слишком выражена. Случай, не прошедший экзамен Американского совета ортодонтов.", "at": {"f": "az_w04", "x": 800, "y": 1800, "w": 604, "h": 450, "W": 3200, "H": 2250}},
