    az6_chain: {"src": "Вебинар 6", "time": "112:15", "n": "Слайд", "t": "Кнопки и эластическая цепочка", "s": "ротация бокового резца", "cap": "На боковой резец приклеена кнопка, цепочка обёрнута вокруг зуба и идёт к опорной кнопке на жевательном зубе. В капе сделаны вырезы.", "at": {"f": "az_w06", "x": 0, "y": 1800, "w": 800, "h": 429, "W": 3200, "H": 3150}},
