    az6_fit: {"src": "Вебинар 6", "time": "138:15", "n": "Слайд", "t": "Зазор", "s": "зубы не поспевают за планом", "cap": "Если посадка со временем ухудшается, зубы «не отслеживают»: капы идут по плану, а зубы отстают из-за нехватки места или недостаточного давления. Между режущими краями и капой виден зазор.", "at": {"f": "az_w06", "x": 0, "y": 2250, "w": 800, "h": 429, "W": 3200, "H": 3150}},
    az6_gap: {"src": "Вебинар 6", "time": "142:15", "n": "Слайд", "t": "Если зазор сохраняется", "s": "проверить контакты", "cap": "Если зазор сохраняется, смотрят по плану, какие зубы движутся на этом шаге. В скученных дугах плотные контакты не дают зубам двигаться — их освобождают сепарацией.", "at": {"f": "az_w06", "x": 800, "y": 2250, "w": 800, "h": 429, "W": 3200, "H": 3150}},
