    az7_tree: {"src": "Вебинар 7", "time": "37:15", "n": "Слайд", "t": "Дерево решений", "s": "короткое или длинное лицо", "cap": "Вертикальная аномалия — глубокий прикус. Короткое лицо: зубоальвеолярная причина — площадки и скошенные аттачменты на премолярах; скелетная — функциональный аппарат у растущих, хирургия у взрослых. Длинное лицо: до 2 мм — относительное внедрение, больше 2 мм — мини-имплантаты.", "at": {"f": "az_w07", "x": 2400, "y": 900, "w": 780, "h": 450, "W": 3200, "H": 2250}},
